271	    private class In extends InputStream {
272	      private int pos;
273	
274	      @Override
275	      public int read() throws IOException {
276	        byte[] b = new byte[1];
277	        return read(b) == -1 ? -1 : toUnsignedInt(b[0]);
278	      }
279	
280	      @Override
281	      public int read(byte[] b, int off, int len) {
282	        if (pos >= bytes.length) {
283	          return -1;
284	        }
285	
286	        int lenToRead = min(len, bytes.length - pos);
287	        arraycopy(bytes, pos, b, off, lenToRead);
288	        pos += lenToRead;
289	        return lenToRead;
